import{_ as a,o as s,c as r,a4 as o}from"./chunks/framework.DzJZdBQK.js";const c=JSON.parse('{"title":"Hbase Indexer - 要求","description":"","frontmatter":{"date":"2018-12-05T12:30:00","title":"Hbase Indexer - 要求","categories":["hbase","hbase indexer"],"tags":["hbase","hbase indexer"]},"headers":[{"level":2,"title":"详情（Details）","slug":"详情-details","link":"#详情-details","children":[{"level":3,"title":"HBase","slug":"hbase","link":"#hbase","children":[]}]},{"level":2,"title":"Solr","slug":"solr","link":"#solr","children":[]},{"level":2,"title":"ZooKeeper","slug":"zookeeper","link":"#zookeeper","children":[]}],"relativePath":"posts/bigdata/hbase-indexer/requirements.md","filePath":"posts/bigdata/hbase-indexer/requirements.md"}'),t={name:"posts/bigdata/hbase-indexer/requirements.md"};function i(l,e,n,d,h,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<p>The following software is required for running the HBase Indexer:</p><p>运行Hbase Indexer需要下面的这些软件:</p><ul><li>HBase 0.94.x</li><li>Solr 4.x in cloud mode</li><li>ZooKeeper 3.x (required by the two above packages)</li></ul><p>All components can be run on a single machine, or they can be run on multiple machines on a cluster.</p><p>所有的组件可以运行在单机，也可运行在多台机器的集群上。</p><h2 id="详情-details" tabindex="-1">详情（Details） <a class="header-anchor" href="#详情-details" aria-label="Permalink to &quot;详情（Details）&quot;">​</a></h2><h3 id="hbase" tabindex="-1">HBase <a class="header-anchor" href="#hbase" aria-label="Permalink to &quot;HBase&quot;">​</a></h3><p>HBase 0.94.x is the supported version of HBase for the HBase Indexer. It is recommended to use the version of HBase 0.94.2 that is bundled with Cloudera CDH 4.2. However, other versions of HBase 0.94.x may also work. CDH 4.2 is currently used for testing.</p><p>Hbase 0.94.x是Hbase Indexer支持的版本。推荐使用Cloudera CDH 4.2附带的HBase 0.94.2版本。尽管，其他的0.94.x版本也能正常工作，但CDH 4.2被用于当前的测试。</p><p>HBase should be configured to use HDFS as its filesystem -- HBase Indexer is not fully functional if the local filesystem implementation is used instead of HDFS.</p><p>Hbase要配置HDFS做为它的文件系统，如果使用本地文件系统而不是HDFS，HBase Indexer就不行完全运行了。</p><h2 id="solr" tabindex="-1">Solr <a class="header-anchor" href="#solr" aria-label="Permalink to &quot;Solr&quot;">​</a></h2><p>Solr 4.x is required for the HBase Indexer, and it must be configured to run in cloud mode. Solr 4.2.0 is currently used for development testing.</p><p>Hbase Indexer 需要Solr 4.x版本，并且要求配置在云模式下运行。Solr 4.2.0是当并开发测试的版本。</p><h2 id="zookeeper" tabindex="-1">ZooKeeper <a class="header-anchor" href="#zookeeper" aria-label="Permalink to &quot;ZooKeeper&quot;">​</a></h2><p>It is recommended that the version of ZooKeeper that is bundled in CDH 4.2 is used.</p><p>推荐使用和CDH4.2附带的ZooKeeper版本。</p>',17)])])}const b=a(t,[["render",i]]);export{c as __pageData,b as default};
